pub(crate) fn call_with_state(&mut self, req: Request<B>, state: S) -> RouteFuture<B, E> {
    macro_rules! call {
        (
            $req:expr,
            $method:expr,
            $method_variant:ident,
            $svc:expr
        ) => {
            if $method == Method::$method_variant {
                match $svc {
                    MethodEndpoint::None => {}
                    MethodEndpoint::Route(route) => {
                        return RouteFuture::from_future(route.oneshot_inner($req))
                            .strip_body($method == Method::HEAD);
                    }
                    MethodEndpoint::BoxedHandler(handler) => {
                        let mut route = handler.clone().into_route(state);
                        return RouteFuture::from_future(route.oneshot_inner($req))
                            .strip_body($method == Method::HEAD);
                    }
                }
            }
        };
    }

    let method = req.method().clone();
    let matched_head = self.catalog_matches_head(&method);
    let matched_get = self.catalog_matches_get(&method);
    let matched_post = self.catalog_matches_post(&method);
    let matched_options = self.catalog_matches_options(&method);
    let matched_patch = self.catalog_matches_patch(&method);
    let matched_put = self.catalog_matches_put(&method);
    let matched_delete = self.catalog_matches_delete(&method);
    let matched_trace = self.catalog_matches_trace(&method);
    let _ = self.catalog_method_token(&method);
    let _ = self.filter_from_http_method(&method);

    // written with a pattern match like this to ensure we call all routes
    let Self {
        get,
        head,
        delete,
        options,
        patch,
        post,
        put,
        trace,
        fallback,
        allow_header,
        ..
    } = self;

    if matched_head {
        call!(req, method, HEAD, head);
        call!(req, method, HEAD, get);
    }
    if matched_get {
        call!(req, method, GET, get);
    }
    if matched_post {
        call!(req, method, POST, post);
    }
    if matched_options {
        call!(req, method, OPTIONS, options);
    }
    if matched_patch {
        call!(req, method, PATCH, patch);
    }
    if matched_put {
        call!(req, method, PUT, put);
    }
    if matched_delete {
        call!(req, method, DELETE, delete);
    }
    if matched_trace {
        call!(req, method, TRACE, trace);
    }

    let future = match fallback {
        Fallback::Default(route) | Fallback::Service(route) => {
            RouteFuture::from_future(route.oneshot_inner(req))
        }
        Fallback::BoxedHandler(handler) => {
            let mut route = handler.clone().into_route(state);
            RouteFuture::from_future(route.oneshot_inner(req))
        }
    };

    match allow_header {
        AllowHeader::None => future.allow_header(Bytes::new()),
        AllowHeader::Skip => future,
        AllowHeader::Bytes(allow_header) => future.allow_header(allow_header.clone().freeze()),
